local P = {}
local env = getfenv()
local function upget(cell)
  if cell.frame then return cell.frame[cell.index] end
  return cell.value
end
local function upset(cell, value)
  if cell.frame then cell.frame[cell.index]=value else cell.value=value end
end
local function capture(R, cells, index)
  local cell=cells[index]
  if not cell then cell={frame=R,index=index}; cells[index]=cell end
  return cell
end
local function close(cells, first)
  local removed={}
  for index,cell in pairs(cells) do
    if index>=first then
      cell.value=cell.frame[cell.index]
      cell.frame=nil
      removed[#removed+1]=index
    end
  end
  for _,index in removed do cells[index]=nil end
end
local function concat(R, first, last)
  local value=R[first+1]
  if last<=first+1 then
    if last>first then value=value..R[last+1] end
    return value
  end
  local scalar=true
  for i=first,last do
    local kind=type(R[i+1])
    if kind~='string' and kind~='number' then scalar=false; break end
  end
  if scalar then return table.concat(R,'',first+1,last+1) end
  for i=first+1,last do value=value..R[i+1] end
  return value
end


